// Import of required libraries
import { test, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { expect } from '@playwright/test';
import { setProjectName, openSaveToDialog } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(108000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await setProjectName(page, 'quarterly:report');
    await page.goto(`${baseUrl}/`);
    await openSaveToDialog(page);

    // The illegal ':' in the project name disables the disk export.
    await expect(page.getByRole('button', { name: 'Save to file' })).toBeDisabled();
    // Only the disk card is gated - the shareable link does not carry a filename.
    await expect(page.getByRole('button', { name: 'Export to Link' })).toBeEnabled();
    await expect(page.getByRole('heading', { name: 'Save to disk' })).toBeVisible();
    // Blocking the export is only safe if the dialog also lets the user fix the name.
    // JSONExportDialog.tsx gates the project-name field on !nativeFileSystemSupported
    // (line 63) but not the disabled guard (line 72), so on Chrome/Edge the user is
    // left with a permanently disabled button and no field to correct - a dead end.
    await expect(
        page.locator('.ExportDialog--json .ProjectName input'),
    ).toBeVisible();
});
